 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # A vertical 5-wall is accompanied by one or more colored seed rows at
    # one end. Extend that horizontal pattern through the full wall height.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == 5]
        if len(rows) < 2 or rows != list(range(min(rows), max(rows) + 1)):
            continue
        top, bot = rows[0], rows[-1]
        for side in (-1, 1):
            start = c + side
            if not (0 <= start < w):
                continue
            # Find a consecutive run of seed rows immediately alongside the wall.
            seed_rows = [r for r in rows if grid[r][start] != 0]
            if not seed_rows:
                continue
            # Seed rows are anchored at an end of the wall.
            if seed_rows[0] not in (top, top + 1) and seed_rows[-1] not in (bot, bot - 1):
                continue
            # Prefer rows carrying a full nonzero stripe; allow seed adjacent
            # rows just outside a wall endpoint (the common two-row case).
            lo, hi = min(seed_rows), max(seed_rows)
            stripes = []
            for r in range(lo, hi + 1):
                if grid[r][start] == 0:
                    continue
                a, b = start, start
                while a - 1 >= 0 and grid[r][a - 1] != 0 and grid[r][a - 1] != 5:
                    a -= 1
                while b + 1 < w and grid[r][b + 1] != 0 and grid[r][b + 1] != 5:
                    b += 1
                stripes.append((r, a, b, grid[r][a:b + 1]))
            if not stripes:
                continue
            # Extend stripe(s) up/down, using the seed rows as a repeating tile.
            seed = {r: vals for r, a, b, vals in stripes}
            seed_indices = sorted(seed)
            width_left = min(a for _, a, _, _ in stripes)
            width_right = max(b for _, _, b, _ in stripes)
            # For these puzzles stripes begin next to the wall and extend outward.
            for r in rows:
                source_r = seed_indices[(r - seed_indices[0]) % len(seed_indices)]
                vals = seed[source_r]
                left = min(c + side, c - side) if side < 0 else c + 1
                # Write the full stripe at its original offset from the wall.
                if side > 0:
                    a = c + 1
                else:
                    a = c - len(vals)
                if a >= 0 and a + len(vals) <= w:
                    out[r][a:a + len(vals)] = vals
            break

    # A horizontal 5-wall has a vertical seed at one of its ends; copy that
    # vertical color sequence sideways across the wall's span.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == 5]
        if len(cols) < 2 or cols != list(range(min(cols), max(cols) + 1)):
            continue
        left, right = cols[0], cols[-1]
        for side in (-1, 1):
            seed_r = r + side
            if not (0 <= seed_r < h):
                continue
            anchor = left if side > 0 else right
            if grid[seed_r][anchor] == 0:
                continue
            seed_vals = []
            rr = seed_r
            step = side
            while 0 <= rr < h and grid[rr][anchor] != 0 and grid[rr][anchor] != 5:
                seed_vals.append((rr, grid[rr][anchor]))
                rr += step
            if not seed_vals:
                continue
            # Fill down/up along the seed rows and across the wall's width.
            for rr0, value in seed_vals:
                for cc in range(left, right + 1):
                    if out[rr0][cc] == 0:
                        out[rr0][cc] = value
            break
    return out
